module pulse_detect(
    input clk, rst_n, data_in,
    output reg data_out
);

    localparam initial_state = 2'd0;
    localparam first_one = 2'd1;
    localparam second_zero = 2'd2;
    localparam last_pulse = 2'd3;
    reg [1:0] state, next_state;
    always @(*) begin 
        case(state)
            initial_state: next_state = data_in? first_one : initial_state;
            first_one:     next_state = ~data_in? second_zero : first_one;
            second_zero:   next_state = data_in? last_pulse : initial_state;
            last_pulse:    next_state = data_in? first_one : initial_state;
        endcase
    end
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            state <= initial_state;
        end else begin
            state <= next_state;
        end
    end

    always @(*) begin
        case(state)
            initial_state: data_out = 1'd0;
            first_one:     data_out = 1'd0;
            second_zero:   data_out = 1'd0;
            last_pulse:    data_out = 1'd1;
        endcase
    end

endmodule
